// Assemble the Night Shift Studio theme (6 Divi 5 pages for a creative studio that works nights) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language soft-saas + the soft-lift style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php nightshift      -> dist/theme-packs/nightshift/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && NSS_DIR=<dir with the six json files> npx tsx scripts/create-nightshift-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.NSS_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/nightshift';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Night Shift Studio',
  tagline: 'Your brand, built while you sleep.',
  audience: 'founders, marketing leads and small-business owners who want a considered brand, website or campaign from a calm studio that delivers a finished draft every morning',
  conversionGoal: 'book a night shift',
  primaryCta: 'Book a night shift',
  accentColorHex: '#4F46E5',
  voice: 'calm, dry and quietly funny. Short sentences, a little sleepy charm, concrete details, no agency jargon.',
  palette: { primary: '#4f46e5', secondary: '#596083', tint: '#f5f6ff', dark: '#1e2140', heading: '#1e2140', body: '#596083' },
  designNotes: 'Soft-saas design language with the soft-lift kit: lavender backgrounds, white rounded cards with soft shadows, a deep indigo accent, Plus Jakarta Sans headings and Figtree body.',
};

const BRAND_FACTS =
  'Night Shift Studio, 214 Kent Avenue, Brooklyn, NY 11249. Phone (718) 555-0133. hello@nightshift.studio. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'work', roleLabel: 'Night Log' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'process', roleLabel: 'Process' },
  { role: 'about', roleLabel: 'The Crew' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'creative_agency', style: 'minimal', color: 'purple', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'nightshift-creative-studio-theme';
const PACK_TITLE = 'Night Shift Studio: Creative Agency Theme (6 Pages)';
const DESCRIPTION =
  'A complete six-page Divi 5 website for a creative studio, design agency, branding practice or any calm, craft-led ' +
  'service business, ready to make your own. Home, Night Log, Services, Process, The Crew and Contact share one soft, ' +
  'dusky identity: lavender backgrounds, a deep indigo accent, rounded cards and buttons that lift on hover, set in Plus ' +
  'Jakarta Sans. The concept is a studio that works from 10pm to 6am, and the copy has a dry, sleepy charm to match. ' +
  'Every section is built from proven, validated recipes and a single design language and style kit, so buttons, ' +
  'accordions, forms and type match on every page, on desktop, tablet and phone. A glowing product-style hero, a ' +
  'ratings strip, a scrolling services row, a work grid, a full-bleed quote, a before-and-after slider, a zigzag of ' +
  'featured stories, project and retainer pricing, a four-step process, a team page with a founder note, FAQs and a ' +
  'contact form are all in place. Names, prices, results and reviews are sample copy: swap in your own and publish. ' +
  'No lorem ipsum, no broken layouts. One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Night Shift Studio: Creative Agency Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page soft indigo Divi 5 website theme for a creative studio or design agency: Home, Work, Services, ' +
    'Process, About and Contact. Calm, rounded, real copy, pricing and portfolio sections.',
  keywords: [
    'divi 5 design studio theme', 'creative studio website template', 'soft saas divi template', 'agency portfolio divi 5 theme',
    'branding studio website template', 'divi 5 multi-page theme',
  ],
};
const PRICE_CENTS = 1200;

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Night Shift pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
